import{_ as o}from"./plugin-vue_export-helper-c27b6911.js";import{r as n,o as r,c as s,f as d,b as e,d as t,a as i,w as c,e as h}from"./app-b0f9f688.js";const p={},_=e("h1",{id:"贫富差距不可避免-且会越来越大",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#贫富差距不可避免-且会越来越大","aria-hidden":"true"},"#"),t(" 贫富差距不可避免，且会越来越大")],-1),l=e("p",null,"早些年我还没有认真读书的时候，我认为上面的话是非常令人绝望的(因为我并不属于富裕的那批人)，但现在我对上面的话有了新的理解。",-1),u=e("p",null,"贫富差距是不可避免的，因为贫富差距是社会发展的必然结果，贫富差距逐步扩大也是社会发展的必然结果。",-1),f=h('<h1 id="为什么有贫富差距" tabindex="-1"><a class="header-anchor" href="#为什么有贫富差距" aria-hidden="true">#</a> 为什么有贫富差距</h1><p>在古老的年代里，生产力低下人们几乎只靠生存环境决定贫富差距，出生在热带雨林的人可以随意捡果子吃，出生在沙漠、寒带的人只能捕猎或者长途跋涉来获取食物。</p><p>随着社会的发展，有了各种先进的生产知识，如果一个人会种田，而且还会各种商业知识，知道种什么可以卖更多钱，那么他就会逐步成为地主阶级。</p><p>到了现代社会，知识在贫富差距上的作用几乎是决定性的，现在全球的富豪很少有靠出售资源获得大量财富的，像贝佐斯、马斯克这种顶级富豪，他们的财富几乎都来自于科技和商业。</p><p>他们为整个人类创造了需要的东西，并且他们也获得了大量的财富。</p><p>无一例外他们都是各自领域的专家，并且他们也为此投入了大量的时间。</p><p>所以照此发展来看，掌握更多的知识，并且懂得如何利用知识变现的人更容易致富。</p><h2 id="为什么贫富差距会越来越大" tabindex="-1"><a class="header-anchor" href="#为什么贫富差距会越来越大" aria-hidden="true">#</a> 为什么贫富差距会越来越大</h2><p>移动互联网兴起以来，普通群众之间会有越来越世风日下的感受，这不是幻觉，实际上社交媒体放大了这种原本不应被看到的贫富差距。</p>',9),m=e("h2",{id:"如何应对",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#如何应对","aria-hidden":"true"},"#"),t(" 如何应对")],-1),x=e("p",null,"首先要接受贫富差距是不可避免的，其次要接受贫富差距会越来越大，最后要接受贫富差距是社会发展的必然结果。",-1),b=e("p",null,"最重要的是让自己变得富有，这件事情是才是重要的...",-1),k=e("p",null,"etc...",-1);function N(V,w){const a=n("RouterLink");return r(),s("div",null,[_,l,u,d(" more "),f,e("p",null,[t("掌握生产知识并会变现的人越来越富有，同时有大多数"),i(a,{to:"/posts/thinking/2024/thinking/be-a-producer.html"},{default:c(()=>[t("消费者")]),_:1}),t("的注意力被掌握生产知识并会变现的人吸引，所以人群之间的贫富差距会越来越大。")]),m,x,b,k])}const C=o(p,[["render",N],["__file","disparity-between-rich-and-poor.html.vue"]]);export{C as default};
